  const wy = Math.cos(y*0.021-t*0.23)*18 + Math.sin(x*0.019+t*0.31)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.55)*110, 75+Math.cos(t*0.38)*55, 0.075, 2.1, 0.0],
    [320+Math.cos(t*0.48)*110, 165+Math.sin(t*0.65)*55, 0.095, 1.8, 1.2],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.45+1)*95, 0.058, 2.4, 2.5],
    [115+Math.cos(t*0.75+1)*85, 185+Math.sin(t*0.58+3)*65, 0.11, 1.6, 3.8],
    [365+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 5.1],
    [240+Math.cos(t*0.32+5)*130, 205+Math.sin(t*0.52)*85, 0.085, 2.0, 0.8],
    [80+Math.sin(t*0.42+3)*70, 40+Math.cos(t*0.62+4)*50, 0.13, 1.4, 4.2],
