    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const aw = Math.sin(d*f - t*sp + ph);
    const iw = Math.sin(d*f*0.65 + t*sp*0.55 + 1.5 + ph*0.5);
    aS += aw; iS += iw;
    for (let k = j+1; k < src.length; k++) {
      const [sX2, sY2, f2, sp2, ph2] = src[k];
      const d2 = Math.sqrt((sx-sX2)**2 + (sy-sY2)**2);
      cross += aw * Math.sin(d2*f2 - t*sp2 + ph2) * 0.08;
    }
  }
  const n = src.length;
  const act = aS/n, inh = iS/n;
  const bg = (Math.sin(sx*0.038+sy*0.023+t*0.75) + Math.sin(sx*0.028-sy*0.038+t*1.05) + Math.sin(sx*0.05+t*0.5)*Math.cos(sy*0.04-t*0.4))/3;
