  const radial = Math.sin(dist*0.06-t*1.8)*0.3 + Math.sin(dist*0.03+t*0.9)*0.2;
  const field = act - inh*0.65 + bg*0.35 + spiral*0.5 + cross + radial;
  const reaction = Math.tanh(field*2.0);
  const lap = Math.sin(sx*0.18)*Math.sin(sy*0.18) + Math.sin((sx+sy)*0.12+t)*0.4 + Math.sin((sx-sy)*0.09-t*0.7)*0.3;
  const cell = Math.tanh(lap*1.4)*0.25;
  const pulse = 0.92 + Math.sin(t*0.6)*0.08;
